class Solution { private fun prime(digit:Char)=digit=='2'||digit=='3'||digit=='5'||digit=='7';fun beautifulPartitions(s:String,k:Int,minLength:Int):Int{val n=s.length;val mod=1_000_000_007L;if(!prime(s[0])||prime(s[n-1]))return 0;fun boundary(position:Int):Boolean{return position==0||position==n||(!prime(s[position-1])&&prime(s[position]))};var dp=LongArray(n+1);dp[0]=1;repeat(k){val next=LongArray(n+1);var running=0L;for(end in 1..n){val start=end-minLength;if(start>=0&&boundary(start))running=(running+dp[start])%mod;if(boundary(end))next[end]=running};dp=next};return dp[n].toInt()} }
